    for char in text:
        if char == '<':
            in_code_block = True
            current_tag = None
        elif char == '>':
            in_code_block = False
            if current_tag:
                tags.add(current_tag)
                if replacer:
                    current_tag = replacer(current_tag)
        elif not in_code_block:
            if char == '[':
